-- Permission vocabulary and system roles of the recruitment module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the recruitment permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('candidate:create'::text, 'candidate'::text, 'create'::text, 'Create candidate'::text),
            ('candidate:delete'::text, 'candidate'::text, 'delete'::text, 'Delete candidate'::text),
            ('candidate:purge'::text, 'candidate'::text, 'purge'::text, 'Purge candidate'::text),
            ('candidate:read'::text, 'candidate'::text, 'read'::text, 'Read candidate'::text),
            ('candidate:restore'::text, 'candidate'::text, 'restore'::text, 'Restore candidate'::text),
            ('candidate:update'::text, 'candidate'::text, 'update'::text, 'Update candidate'::text),
            ('interview:read'::text, 'interview'::text, 'read'::text, 'Read interview'::text),
            ('job_application:create'::text, 'job_application'::text, 'create'::text, 'Create job application'::text),
