            ('offer_letter_template:create'::text, 'offer_letter_template'::text, 'create'::text, 'Create offer letter template'::text),
            ('offer_letter_template:delete'::text, 'offer_letter_template'::text, 'delete'::text, 'Delete offer letter template'::text),
            ('offer_letter_template:purge'::text, 'offer_letter_template'::text, 'purge'::text, 'Purge offer letter template'::text),
            ('offer_letter_template:read'::text, 'offer_letter_template'::text, 'read'::text, 'Read offer letter template'::text),
            ('offer_letter_template:restore'::text, 'offer_letter_template'::text, 'restore'::text, 'Restore offer letter template'::text),
