            ('requisition_skill:read'::text, 'requisition_skill'::text, 'read'::text, 'Read requisition skill'::text),
            ('requisition_skill:restore'::text, 'requisition_skill'::text, 'restore'::text, 'Restore requisition skill'::text),
            ('requisition_skill:update'::text, 'requisition_skill'::text, 'update'::text, 'Update requisition skill'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('candidate:create'::text, 'candidate'::text, 'create'::text, 'Create candidate'::text),
            ('candidate:delete'::text, 'candidate'::text, 'delete'::text, 'Delete candidate'::text),
            ('candidate:purge'::text, 'candidate'::text, 'purge'::text, 'Purge candidate'::text),
            ('candidate:read'::text, 'candidate'::text, 'read'::text, 'Read candidate'::text),
            ('candidate:restore'::text, 'candidate'::text, 'restore'::text, 'Restore candidate'::text),
