            ('offer_letter_template:read'::text, 'offer_letter_template'::text, 'read'::text, 'Read offer letter template'::text),
            ('offer_letter_template:restore'::text, 'offer_letter_template'::text, 'restore'::text, 'Restore offer letter template'::text),
            ('offer_letter_template:update'::text, 'offer_letter_template'::text, 'update'::text, 'Update offer letter template'::text),
            ('recruitment_stage:create'::text, 'recruitment_stage'::text, 'create'::text, 'Create recruitment stage'::text),
            ('recruitment_stage:delete'::text, 'recruitment_stage'::text, 'delete'::text, 'Delete recruitment stage'::text),
            ('recruitment_stage:purge'::text, 'recruitment_stage'::text, 'purge'::text, 'Purge recruitment stage'::text),
