            ('recruitment_stage:update'::text, 'recruitment_stage'::text, 'update'::text, 'Update recruitment stage'::text),
            ('requisition_skill:create'::text, 'requisition_skill'::text, 'create'::text, 'Create requisition skill'::text),
            ('requisition_skill:delete'::text, 'requisition_skill'::text, 'delete'::text, 'Delete requisition skill'::text),
            ('requisition_skill:purge'::text, 'requisition_skill'::text, 'purge'::text, 'Purge requisition skill'::text),
            ('requisition_skill:read'::text, 'requisition_skill'::text, 'read'::text, 'Read requisition skill'::text),
            ('requisition_skill:restore'::text, 'requisition_skill'::text, 'restore'::text, 'Restore requisition skill'::text),
            ('requisition_skill:update'::text, 'requisition_skill'::text, 'update'::text, 'Update requisition skill'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
